package model;
public class Review { private int reviewId,foodId,rating; private String customerName,reviewText,reviewDate; public Review(){} public int getReviewId(){return reviewId;} public void setReviewId(int v){reviewId=v;} public int getFoodId(){return foodId;} public void setFoodId(int v){foodId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public int getRating(){return rating;} public void setRating(int v){rating=v;} public String getReviewText(){return reviewText;} public void setReviewText(String v){reviewText=v;} public String getReviewDate(){return reviewDate;} public void setReviewDate(String v){reviewDate=v;} }
